class TextFormatter implements Formatter { format(s: LogSummary) { return 'text'; } }
class JSONFormatter implements Formatter { format(s: LogSummary) { return JSON.stringify(s); } }
class FormatterRegistry {
  private map = new Map<string, () => Formatter>();
  register(name: string, factory: () => Formatter) { this.map.set(name, factory); }
  get(name: string): Formatter { const f = this.map.get(name); return f ? f() : new TextFormatter(); }
